(async function(){
const $=id=>document.getElementById(id),M=TwinModel;
const controls=[...document.querySelectorAll('button,input,select')];controls.forEach(el=>el.disabled=true);
try{
const [model,report,patients]=await Promise.all(['trained-model.json','benchmark.json','patients.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw Error('Could not load '+url);return r.json();}));
let patient=patients[0],origin=patient.start,revealed=false,playing=false,current,ledger=[],quality='complete';
const stats=report.benchmarks[report.selected],eventStats=report.event_benchmarks[report.event_selected],fmt=(n,d=1)=>Number(n).toFixed(d),pct=n=>fmt(n*100)+'%',clock=i=>`Day ${Math.floor(i/288)+1} · ${String(Math.floor(i%288/12)).padStart(2,'0')}:${String((i%12)*5).padStart(2,'0')} IST`;
function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([type==='application/json'?JSON.stringify(data,null,2):data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('toast').textContent='Download ready';$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2200);}
$('patient').innerHTML=patients.map(p=>`<option value="${p.profile.id}">${p.profile.name}</option>`).join('');
function chart(){const w=720,h=274,L=43,R=17,T=18,B=36,x=m=>L+(m+360)/480*(w-L-R),y=v=>T+(320-v)/280*(h-T-B),now=x(0),end=x(120),hist=current.rows.slice(origin-72,origin+1).map((r,i)=>Number.isFinite(r[0])?`${x((i-72)*5)},${y(r[0])}`:'').filter(Boolean).join(' '),pred=current.pred,g=current.x[5],band=`${now},${y(g)} ${end},${y(pred+model.interval)} ${end},${y(pred-model.interval)}`;
const future=revealed?patient.readings.slice(origin,origin+25).map((r,i)=>`${x(i*5)},${y(r[0])}`).join(' '):'';
$('chart').innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Past glucose, saved two-hour forecast${revealed?' and actual future readings revealed':''}"><rect x="${now}" y="${T}" width="${end-now}" height="${h-T-B}" fill="#f6f9f4"/>${[60,120,180,240,300].map(v=>`<line x1="${L}" y1="${y(v)}" x2="${w-R}" y2="${y(v)}" stroke="${v===180?'#d4b783':'#eaf0ea'}" stroke-dasharray="3 4"/><text x="${L-9}" y="${y(v)+3}" text-anchor="end" fill="#91a095" font-size="9">${v}</text>`).join('')}<polygon points="${band}" fill="#dceade"/><polyline points="${hist}" fill="none" stroke="#377f71" stroke-width="2.4" stroke-linejoin="round"/><line x1="${now}" y1="${y(g)}" x2="${end}" y2="${y(pred)}" stroke="#7e9e79" stroke-width="2" stroke-dasharray="5 5"/>${revealed?`<polyline points="${future}" fill="none" stroke="#4388bb" stroke-width="2.2"/><circle cx="${end}" cy="${y(patient.readings[origin+24][0])}" r="4" fill="#4388bb"/>`:''}<line x1="${now}" x2="${now}" y1="${T}" y2="${h-B}" stroke="#a7bbaa" stroke-dasharray="3 4"/><circle cx="${now}" cy="${y(g)}" r="4" fill="#337c6d" stroke="white" stroke-width="2"/><circle cx="${end}" cy="${y(pred)}" r="4" fill="#789c75" stroke="white" stroke-width="2"/><text x="${end-10}" y="${y(pred)-12}" text-anchor="end" font-size="10" fill="#577851">Forecast ${Math.round(pred)}</text>${[-360,-240,-120,0,120].map(m=>`<text x="${x(m)}" y="${h-12}" text-anchor="middle" fill="#91a095" font-size="9">${m===0?'Forecast issued':m===120?'+2 hours':m/60+'h'}</text>`).join('')}</svg>`;}
function render(){const p=patient.profile,s=M.snapshot(patient,origin,quality),pred=M.predict(model,s.x),prob=M.probability(model,s.x),elevated=s.x[5]>180,alert=!elevated&&prob>=model.event_model.cutoff;current={...s,pred,prob,alert,issued:origin};
$('initials').textContent=p.initials;$('patient-meta').textContent=`${p.id} · ${p.age} years · ${p.sex} · ${p.city}, India · fictional`;$('sync').textContent=clock(origin);$('glucose').textContent=Math.round(s.x[5]);$('forecast').textContent=Math.round(pred);$('forecast-range').textContent=`90% residual band: ${Math.round(pred-model.interval)}–${Math.round(pred+model.interval)} mg/dL`;$('risk').textContent=elevated?'Already elevated':alert?'Spike risk flagged':'No spike alert';$('risk').style.color=elevated||alert?'#b27a3b':'#377f71';$('insight-title').textContent=alert?'An early spike warning.':elevated?'Glucose is already elevated.':'No spike warning at this time.';$('insight-text').textContent=`At ${clock(origin+24)}, the glucose forecast is ${Math.round(pred)} mg/dL. A separate trained classifier estimates ${pct(prob)} endpoint elevation risk. Alert cutoff: ${pct(model.event_model.cutoff)}, chosen on validation patients to favour catching spikes. Both data streams are used.`;
if(elevated)$('insight-text').textContent=`Current glucose is already above 180 mg/dL. The +2-hour value forecast is ${Math.round(pred)} mg/dL. This origin is excluded from new-spike prediction and event scoring.`;
const effects=[['Historical HbA1c',2,7],['Historical BMI',1,27],['Genetic marker (simulated)',4,1],['Recent glucose trend',11,0],['Sleep duration',12,7],['Recent activity',13,500],['Heart-rate variability',14,40]].map(([name,i,v])=>{const z=s.x.slice();z[i]=v;return {name,value:pred-M.predict(model,z)};}).sort((a,b)=>Math.abs(b.value)-Math.abs(a.value));$('drivers').innerHTML=effects.slice(0,3).map(d=>`<div class="driver"><span>${d.name}</span><b>${d.value>=0?'+':''}${fmt(d.value)} mg/dL</b></div>`).join('')+'<small class="explain-note">One-feature sensitivity versus reference values; not causal effects.</small>';
$('baseline').innerHTML=[['HbA1c',p.hba1c,'%'],['Body mass index',p.bmi,'kg/m²'],['Diagnosis history',p.years,'years'],['Genetic marker',p.gene,'synthetic copies']].map(([k,v,u])=>`<div><small>${k}</small><b>${v}<em>${u}</em></b></div>`).join('');$('wearables').innerHTML=[['☾','Sleep',fmt(s.x[12]),'h'],['↗','Steps, last hour',Math.round(s.x[13]),'steps'],['♡','HRV / heart rate',`${Math.round(s.x[14])} / ${Math.round(s.x[15])}`,'ms / bpm']].map(([ic,k,v,u])=>`<div class="wearable"><div><i>${ic}</i>${k}</div><b>${v} <small>${u}</small></b></div>`).join('');
$('ehr-json').textContent=JSON.stringify({source:'synthetic_ehr',patient_id:p.id,age:p.age,sex:p.sex,diagnosis:'Type 2 Diabetes',diagnosis_years:p.years,hba1c:p.hba1c,bmi:p.bmi,genetic_marker:p.gene},null,2);$('sensor-json').textContent=JSON.stringify({source:'synthetic_wearables',patient_id:p.id,observed_through:clock(origin),glucose:s.x[5],slope_30min:s.x[11],sleep:s.x[12],steps_last_hour:s.x[13],hrv:s.x[14],heart_rate:s.x[15],quality,future_readings_used_for_prediction:0},null,2);$('events').innerHTML=s.rows.slice(-10).reverse().map((r,j)=>`<tr><td>${clock(origin-j)}</td><td>${p.id}</td><td>${r[0]===null?'Missing → past value carried':fmt(r[0])}</td><td>Simulated CGM</td><td>${r[0]===null?'Gap':'Available'}</td></tr>`).join('');
$('timeline').value=origin;$('time-label').textContent=clock(origin);$('play').textContent=playing?'Ⅱ Pause replay':'▷ Play replay';chart();scenario();outcome();}
function scenario(){const z=current.x.slice();z[12]=+$('sleep').value;z[13]=+$('steps').value;$('sleep-value').textContent=fmt(z[12]);$('steps-value').textContent=z[13].toLocaleString();const v=M.predict(model,z),d=v-current.pred;$('scenario-output').textContent=`${Math.round(v)} mg/dL (${d>=0?'+':''}${fmt(d)})`;}
function outcome(){if(!revealed){$('outcome').innerHTML='<b>Can it predict what happens next?</b><p>1. The model has issued a forecast using past data only. 2. Reveal the next two hours to check it.</p>';$('reveal').textContent='Reveal actual outcome →';$('actual-legend').classList.add('hidden');return;}
const actual=patient.readings[origin+24][0],trueEvent=current.x[5]<=180&&actual>180,eligible=current.x[5]<=180;const verdict=eligible?(trueEvent===current.alert?'Correct event decision':current.alert?'False alarm':'Missed event'):'Already elevated at forecast time';$('outcome').innerHTML=`<b>${verdict}</b><div class="outcome-numbers"><span>Predicted <strong>${Math.round(current.pred)}</strong> mg/dL</span><span>Actual at +2h <strong>${Math.round(actual)}</strong> mg/dL</span><span>Error <strong>${fmt(Math.abs(actual-current.pred))}</strong> mg/dL</span></div><p>${eligible?(trueEvent?'A new endpoint elevation occurred.':'No new endpoint elevation occurred.'):'This window is excluded from new-spike event scoring.'} Saved prediction has not changed after revealing the future.</p>`;$('reveal').textContent='Advance 2 hours & predict again →';$('actual-legend').classList.remove('hidden');}
function record(){const key=patient.profile.id+':'+origin+':'+quality;if(!ledger.some(r=>r.key===key))ledger.push({key,patient_id:patient.profile.id,issued_tick:origin,target_tick:origin+24,prediction:current.pred,actual:patient.readings[origin+24][0],current:current.x[5],quality});}
function move(i){origin=Math.max(72,Math.min(patient.readings.length-25,Math.round(i)));revealed=false;render();}
function select(){patient=patients.find(p=>p.profile.id===$('patient').value);origin=patient.start;revealed=false;$('timeline').max=patient.readings.length-25;$('sleep').value=patient.readings[origin][1];$('steps').value=patient.readings.slice(origin-11,origin+1).reduce((s,r)=>s+r[2],0);render();}
$('patient').onchange=()=>{$('example').value='';select();};$('sleep').oninput=scenario;$('steps').oninput=scenario;$('timeline').oninput=()=>{playing=false;$('example').value='';move(+$('timeline').value);};$('quality').onchange=()=>{quality=$('quality').value;revealed=false;$('example').value='';render();};$('next').onclick=()=>{$('example').value='';move(origin+1);};$('reveal').onclick=()=>{playing=false;if(revealed){$('example').value='';move(origin+24);}else{record();revealed=true;render();}};$('play').onclick=()=>{playing=!playing;$('example').value='';render();};setInterval(()=>{if(playing){if(origin>=patient.readings.length-25){playing=false;render();}else move(origin+1);}},2500);
const examples={};for(const pt of patients){for(let i=72;i<pt.readings.length-24;i+=6){const x=M.snapshot(pt,i).x;if(x[5]>180)continue;const actual=pt.readings[i+24][0]>180,alert=M.probability(model,x)>=model.event_model.cutoff,key=actual?(alert?'hit':'miss'):(alert?'false':'normal');if(!examples[key])examples[key]={patient:pt,index:i};if(Object.keys(examples).length===4)break;}if(Object.keys(examples).length===4)break;}
$('example').onchange=()=>{const e=examples[$('example').value];if(!e)return;playing=false;quality='complete';$('quality').value='complete';$('patient').value=e.patient.profile.id;select();move(e.index);};
function view(v){document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===v));['overview','streams','model'].forEach(n=>$(n+'-view').classList.toggle('hidden',v!==n));const title={overview:'Patient overview',streams:'Data streams',model:'Model & benchmarks'}[v];$('page-title').textContent=title;$('crumb').textContent=title;}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$('inspect').onclick=()=>view('model');
$('validation').innerHTML=[['Average forecast error',fmt(stats.mae),'mg/dL','Held-out patient timelines'],['Spikes caught',pct(eventStats.recall),'','Dedicated spike classifier recall'],['Alerts that were correct',pct(eventStats.precision),'','Dedicated spike classifier precision'],['Held-out patients',report.split.test.patients,'patients',`${stats.n.toLocaleString()} rolling forecasts`]].map(([a,b,c,d])=>`<article class="metric"><div>${a}</div><h2>${b}<small>${c}</small></h2><p>${d} · synthetic only</p></article>`).join('');
function metricTable(rows){return '<div class="table-wrap"><table><thead><tr><th>Method</th><th>Avg error ↓</th><th>RMSE ↓</th><th>Alerts correct ↑</th><th>Spikes caught ↑</th><th>F1 ↑</th></tr></thead><tbody>'+rows.map(([name,s])=>`<tr class="${name===report.selected?'selected-row':''}"><td>${name}${name===report.selected?' ★ deployed':''}</td><td>${fmt(s.mae)}</td><td>${fmt(s.rmse)}</td><td>${pct(s.precision)}</td><td>${pct(s.recall)}</td><td>${fmt(s.f1,3)}</td></tr>`).join('')+'</tbody></table></div>';}
$('benchmark-table').innerHTML=metricTable(Object.entries(report.benchmarks));$('ablation-table').innerHTML=metricTable([[report.selected,stats],...Object.entries(report.ablations)]);$('stress-table').innerHTML=metricTable([['Clean sensors',stats],...Object.entries(report.stress)]);$('subgroup-table').innerHTML=metricTable(Object.entries(report.subgroups));
$('event-table').innerHTML='<div class="table-wrap"><table><thead><tr><th>Event detector</th><th>Alerts correct</th><th>Spikes caught</th><th>F1</th><th>AUROC</th></tr></thead><tbody>'+Object.entries(report.event_benchmarks).map(([name,s])=>`<tr><td>${name}${name===report.event_selected?' ★ deployed':''}</td><td>${pct(s.precision)}</td><td>${pct(s.recall)}</td><td>${fmt(s.f1,3)}</td><td>${fmt(s.auroc,3)}</td></tr>`).join('')+'</tbody></table></div><p class="model-copy">Model and raw alert cutoff selected by validation F2, which weights recall more than precision. Calibration on separate patients converts the raw cutoff to '+pct(model.event_model.cutoff)+'. Test probability Brier score: '+fmt(eventStats.brier,3)+'. The alert can trigger even when the point forecast is below 180 because it represents risk, not certainty.</p>';
$('confusion').innerHTML=`<div class="confusion">${[['Correct alerts',eventStats.tp],['False alarms',eventStats.fp],['Missed spikes',eventStats.fn],['Correct non-alerts',eventStats.tn]].map(([a,b])=>`<div>${a}<b>${b}</b></div>`).join('')}</div>`;
$('method-summary').innerHTML=`<p><b>Deployed model:</b> ${report.selected}. Selected by the lowest average error on validation patients, before examining test results.</p><p><b>Patient separation:</b> 54 training, 12 validation, 12 calibration and 12 test patients. Each has 8 days of 5-minute sensor data. No patient appears in two cohorts.</p><p><b>Rolling evaluation:</b> forecast every 30 minutes, using only data available then; compare with the actual reading 120 minutes later. New-spike scoring includes origins at or below 180 mg/dL.</p><p><b>Grouped cross-validation:</b> three patient-separated training folds; errors ${report.grouped_cv_mae.map(v=>fmt(v)).join(', ')} mg/dL.</p><p><b>Chronological test:</b> train on days 1–5 with labels ending before the cutoff, test on days 7–8. Error: ${fmt(report.temporal.mae)} mg/dL. This is a separate robustness experiment on training-cohort patients.</p><p><b>Patient bootstrap:</b> 500 resamples. Test mean-error 95% interval: ${report.mae_patient_bootstrap_95.map(v=>fmt(v)).join('–')} mg/dL.</p><p><b>Uncertainty:</b> separate calibration patients set the ±${fmt(model.interval)} mg/dL residual band. Test coverage: ${pct(report.interval.test_coverage)}. Overlapping windows prevent a formal independent-sample guarantee.</p><p><b>Risk scores:</b> logistic mapping fitted on calibration patients. Dedicated alert classifier test AUROC ${fmt(eventStats.auroc,3)}, average precision ${fmt(eventStats.average_precision,3)}, Brier score ${fmt(eventStats.brier,3)}. These are synthetic-only results.</p>`;
$('selection-table').innerHTML='<div class="table-wrap"><table><thead><tr><th>Candidate</th><th>Validation avg error (mg/dL)</th></tr></thead><tbody>'+report.validation.map(r=>`<tr><td>${r.model}</td><td>${fmt(r.mae)}</td></tr>`).join('')+'</tbody></table></div>';
$('export').onclick=()=>download(`twinlab-${patient.profile.id}.json`,{prototype:'Twinlab v2',synthetic:true,model:report.selected,patient:patient.profile,issued_at:clock(origin),feature_names:model.features,features:current.x,prediction_120min:current.pred,interval:[current.pred-model.interval,current.pred+model.interval],new_spike_probability:current.x[5]<=180?current.prob:null,event_model:report.event_selected,new_spike_alert:current.alert,actual_if_revealed:revealed?patient.readings[origin+24][0]:null,demonstrations:ledger,benchmark:report});$('download-report').onclick=()=>download('twinlab-benchmarks.json',report);$('download-ledger').onclick=()=>download('twinlab-revealed-forecasts.csv','patient,origin_tick,target_tick,current,prediction,actual,quality\n'+ledger.map(r=>[r.patient_id,r.issued_tick,r.target_tick,r.current,r.prediction,r.actual,r.quality].join(',')).join('\n'),'text/csv');select();$('loading').classList.add('hidden');
controls.forEach(el=>el.disabled=false);
}catch(e){$('loading').textContent='The model could not load. Please reload the page. '+e.message;console.error(e);}
})();
